import { NgModule } from '@angular/core';
import { PageHeaderModule } from 'src/app/view/components/app/page-header/page-header.module';
import { CommonModule, DatePipe } from '@angular/common';
import { UserDetailRequestComponent } from './user-detail-request.component';
import { HttpClientModule, HTTP_INTERCEPTORS } from '@angular/common/http';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { IonicModule } from '@ionic/angular';
import { PersianDateModule } from 'src/app/core/pipe/persian-date/persian-date.module';
import { AccountInterceptor } from 'src/app/core/utility/account.interceptor';
import { AdminService } from 'src/app/data/service/admin/admin.service';
import { UserService } from 'src/app/data/service/user/user.service';
import { FooterModule } from 'src/app/view/components/app/footer/footer.module';
import { LoadingModule } from 'src/app/view/components/common/loading/loading.module';
import { UserDetailRequestRoutingModule } from './user-detail-request-routing.module';

@NgModule({
  declarations: [UserDetailRequestComponent],
  imports: [
    PageHeaderModule,
    CommonModule,
    UserDetailRequestRoutingModule,
    IonicModule,
    HttpClientModule,
    FooterModule,
    FormsModule,
    ReactiveFormsModule,
    PersianDateModule,
    LoadingModule
  ],
  providers: [
    AdminService,
    DatePipe,
    UserService,
    {
      provide: HTTP_INTERCEPTORS,
      useClass: AccountInterceptor,
      multi: true
    }
  ]
})
export class UserDetailRequestModule { }
